    for (long long i = 1, value = 1; value <= n; ++i, value += i) {
        triangular.push_back(value);
    }

    int left = 0;
    int right = static_cast<int>(triangular.size()) - 1;

    while (left <= right) {
        long long sum = triangular[left] + triangular[right];
